'use client';
import { ToggleGroup } from "./toggle-group.js";
import { ToggleGroupItem } from "./toggle-group-item.js";
//#region src/components/toggle-group/index.ts
/**
* Display a group of buttons that can be toggled between.
*
* @example
* <ToggleGroup aria-label="Label" onChange={(value) => console.log(value)}>
*   <ToggleGroup.Item value='1'>Toggle 1</ToggleGroup.Item>
*   <ToggleGroup.Item value='2'>Toggle 2</ToggleGroup.Item>
*   <ToggleGroup.Item value='3'>Toggle 3</ToggleGroup.Item>
* </ToggleGroup>
*/
const ToggleGroupComponent = Object.assign(ToggleGroup, { Item: ToggleGroupItem });
ToggleGroupComponent.Item.displayName = "ToggleGroup.Item";
//#endregion
export { ToggleGroupComponent as ToggleGroup, ToggleGroupItem };
